// Revenue Engine - conversion fix: ensure paidEvents increments on successful checkout
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const REVENUE_LOG = '/var/log/revenue_events.log';

function logEvent(type, data) {
  const entry = {
    ts: new Date().toISOString(),
    type,
    data,
    id: crypto.randomUUID()
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(entry) + '\n');
  return entry;
}

function recordPaidEvent(amount, currency, customerId) {
  const event = logEvent('paid', { amount, currency, customerId });
  // Increment in-memory counter (persisted via periodic sync)
  global.__revenuePaidEvents = (global.__revenuePaidEvents || 0) + 1;
  global.__revenueTotal = (global.__revenueTotal || 0) + amount;
  return event;
}

function getStats() {
  return {
    paidEvents: global.__revenuePaidEvents || 0,
    totalRevenue: global.__revenueTotal || 0,
    conversionRate: global.__revenueLeads > 0 ? (global.__revenuePaidEvents / global.__revenueLeads) : 0
  };
}

module.exports = { recordPaidEvent, getStats, logEvent };
